int64_t vec_dim(const char* vname) {
    if (str_eq(vname, "vec2")) {
        return 2;
    }
    if (str_eq(vname, "vec3")) {
        return 3;
    }
    if (str_eq(vname, "vec4")) {
        return 4;
    }
    return 0;
}

bool vec_comp_ok(char c, int64_t dim) {
    if ((c == 'x') || (c == 'y')) {
        return true;
    }
    if (c == 'z') {
        return (dim >= 3);
    }
    if (c == 'w') {
        return (dim >= 4);
    }
    return false;
}

int64_t vec_swizzle_size(const char* vname, const char* field) {
    int64_t dim = vec_dim(vname);
    if (dim == 0) {
        return 0;
    }
    if ((str_len(field) < 1) || (str_len(field) > 4)) {
        return 0;
    }
    for (int64_t i = 0; i < str_len(field); i++) {
        if (!vec_comp_ok(field[i], dim)) {
            return 0;
        }
    }
    return str_len(field);
}

